/**
 * Unified ToolStep type — canonical model for tool execution steps.
 *
 * Backend (Python ToolStep) and frontend use the same shape:
 * - status: "pending" | "running" | "done" | "failed"
 * - id: tool_call_id (string)
 * - name: display name generated by backend i18n
 *
 * This replaces the legacy StepItem interface and unifies real-time
 * and historical step formats.
 */

export interface ToolStep {
  id: string
  tool: string
  tool_name?: string
  name?: string
  status: "pending" | "running" | "done" | "failed"
  input?: Record<string, any>
  output?: string
  duration_ms?: number
  tool_call_id?: string
  tool_meta?: {
    display_name?: string
    affected_path_keys?: string[]
  }
}

/** Derive active (running) tools from a list of steps. */
export function getActiveTools(steps: ToolStep[] | undefined): Set<string> {
  const toolSet = new Set<string>()
  if (!steps) return toolSet
  for (const step of steps) {
    if (step.status === "running") {
      const toolId = step.tool || step.tool_name || ""
      if (toolId) toolSet.add(toolId.toLowerCase())
    }
  }
  return toolSet
}
